 function factionMatches(a,b){if(normalized(a||'Aeldari')===normalized(b||'Aeldari'))return true;const n=x=>{const key=normalized(x),f=catalog.factions?.find(f=>normalized(f.name)===key||(f.aliases||[]).some(a=>normalized(a)===key));return f?normalized(f.name):['asuryani','aeldari'].includes(key)?'aeldari':key;};return n(a||'Aeldari')===n(b||'Aeldari');}
 function ruleMemberships(rule){return Array.isArray(rule.memberships)?rule.memberships:[{faction:rule.faction,detachments:rule.detachment?[rule.detachment]:[]}];}
 function ruleFactions(rule){return [...new Set(ruleMemberships(rule).map(m=>m.faction))];}
 function ruleDetachments(rule,faction){return [...new Set(ruleMemberships(rule).filter(m=>m.faction==='*'||factionMatches(m.faction,faction)).flatMap(m=>m.detachments))];}
 function ruleInFaction(rule,faction){return ruleFactions(rule).some(f=>f==='*'||factionMatches(f,faction));}
 function ruleInArmy(rule,army){
  if(rule.membershipFaction&&rule.membershipFaction!=='*'&&!factionMatches(rule.membershipFaction,army.faction))return false;
  const memberships=ruleMemberships(rule).filter(m=>m.faction==='*'||factionMatches(m.faction,army.faction));
  if(!memberships.length)return false;if(memberships.some(m=>!m.detachments.length))return true;
  const selected=armyDetachments(army).map(normalized);return memberships.some(m=>m.detachments.some(d=>selected.includes(normalized(d))));
 }
 function unitInfo(entry,faction='Aeldari'){const allies=typeof module!=='undefined'&&module.exports?require('./allies.js'):root.WarPlannerAllies;if(allies)return allies.resolve(catalog,entry,faction);const key=normalized(typeof entry==='object'?entry.name:entry);return catalog.units.find(u=>normalized(u.name)===key&&factionMatches(u.faction,faction));}
 function unitInRule(unit,rule,army){const source=unitInfo(unit,army.faction),allies=typeof module!=='undefined'&&module.exports?require('./allies.js'):root.WarPlannerAllies;if(allies&&!allies.allowsRule(catalog,rule,source,army))return false;if(!source&&catalog.units.some(u=>u.allied&&factionMatches(u.faction,army.faction)&&normalized(u.name)===normalized(unit.name)))return false;return true;}
 function unitHasRule(unit,id,faction='Aeldari',army=null){if(unitInfo(unit,faction)?.abilities.some(a=>a.id===id))return true;const allies=typeof module!=='undefined'&&module.exports?require('./allies.js'):root.WarPlannerAllies;return !!(id==='deep-strike'&&army&&allies?.grantsDeepStrike(catalog,army,unit));}
 const categories={ability:'Ability',army:'Army / Detachment',core:'Core Rule','core-stratagem':'Core Stratagems',stratagem:'Stratagem',enhancement:'Enhancement'};
 function core(id,title,body,why,question,answer,section,window){return {id,title,body,why,question,answer,section,window,sourceIds:['core'],status:'official-checked',kind:'Core sequence',category:'core'};}
 const phases=[
  {name:'Command',intro:'Resolve the opening in order, then make your command decisions.',steps:[
   core('command-start','Start of Command','Resolve rules triggered at the start of the active player’s Command phase. This is a separate window from the later Command Abilities step.','Timing words matter: “at the start” happens before gaining Core CP.','Where does a start-of-phase ability belong?','In this opening window, before the Core CP step. Check whether the ability applies in your turn, the opponent’s turn, or both.','08.01','start'),
   core('command-cp','Gain Command Points','Each player gains one Core Command Point, even though only one player is taking this turn.','Separate Core CP from additional CP awarded by an army rule.','Does the opponent gain this CP too?','Yes. Both players gain the Core CP in each Command phase. This screen teaches the step; it does not keep a CP balance.','08.02','core-cp'),
   core('command-shock','Battle-shock','The active player checks units that are already battle-shocked or at or below half-strength. Roll 2D6 against an applicable Leadership value; meeting or exceeding it succeeds. A unit already battle-shocked recovers here if its roll succeeds.','Do not automatically clear Battle-shock at the start of the turn. The 11th-edition test includes units exactly at half-strength.','A five-model unit has two models left. Must you check it?','Yes: it is at or below half-strength. Attached units use the appropriate starting-strength rules; do not treat a surviving leader as a fresh unit without checking them.','01.06–01.07; 08.03','shock'),
   core('command-abilities','Command Abilities','Now resolve rules triggered in the Command phase that do not belong to a specific start, end, Core CP, or Battle-shock window.','A heading saying “Command” is not enough; the ability’s wording determines its place.','Should you resolve a start-of-phase rule here?','No. Keep specific triggers in their own windows. Optional choices need their conditions and eligible targets checked before you use them.','08.04','act'),
   core('command-end','End of Command','Resolve end-of-Command-phase rules other than mission rules first. Then consult the mission for anything achieved or triggered at this point.','Mission instructions come after the other end-of-phase rules in this sequence.','When do you consult scoring instructions?','At the mission’s specified timing. This app does not infer a mission or calculate score; consult the pack you are playing.','08.05','end')
  ]},
  {name:'Movement',intro:'Move one unit at a time, with a purpose and a clear view of what follows.',steps:[
   core('movement-start','Start of Movement','Resolve rules triggered at the start of the active player’s Movement phase before selecting units to move.','Opening triggers cannot be saved for an arbitrary point later in the phase.','What needs to happen before the first unit moves?','Check explicit start-of-phase wording. Movement-triggered abilities wait for their own selection, setup, or move-end event.','09.01','start'),
   core('movement-select','Unit Movement','Select an unselected friendly unit, including units in reserve or embarked in a transport, then choose a legal move type. Repeat until every unit has been selected—even units that remain stationary.','Movement is not just choosing the models you want to push forward.','Does an unmoving unit still need to be selected?','Yes. Remain stationary is a choice in the sequence. For other units, check normal, advance, fall-back, disembark, and ingress eligibility.','09.02–09.07','act'),
   core('movement-arrivals','Transports & Reserves','Disembark and ingress are move types in this edition, not a generic extra movement step after all other movement. Check their own eligibility and setup restrictions.','The order of a transport’s move and its passengers’ move can change their options.','Can you assume every disembarking unit may charge?','No. Rapid, tactical, and combat disembark modes have different consequences. Review section 18.04 before making the choice. Reserve arrival also needs its permitted round and placement checked.','18.03–18.04; 20.04','arrivals'),
   core('movement-end','End of Movement','After the move selections are complete, resolve rules triggered at the end of the Movement phase.','This is where a pending effect or a target choice may matter to the rest of your turn.','Did an earlier choice leave a consequence to resolve now?','Check any ability used earlier for an end-of-phase instruction. Also check for fresh choices whose trigger is specifically the end of Movement.','09.03','end')
  ]},
  {name:'Shooting',intro:'Choose your sequence deliberately. Earlier attacks may help later units.',steps:[
   core('shooting-start','Start of Shooting','Resolve rules triggered at the start of the active player’s Shooting phase.','Before-shooting and after-shooting abilities are different windows.','Must every ability usable in this phase happen now?','No. Look for its exact trigger. Some choices must be made before selecting a unit; others happen only after attacks resolve.','10.01','start'),
   core('shooting-select','Unit Shooting','Select an eligible unit that has not shot this phase. Check whether normal, assault, close-quarters, or indirect shooting is permitted. An Advance normally restricts you to eligible Assault weapons.','Do not apply an old-edition exception by memory. The shooting type determines the rules.','What should you check for a unit that Advanced?','Check assault-shooting eligibility and its Assault weapons. Also consider any special rule that changes the general restrictions. Fall-back consequences must be checked separately.','10.02; 10.04–10.07','select'),
   core('shooting-attacks','Attacks','Check range, visibility, and target restrictions for each selected weapon. Resolve attacks using the current attack sequence and the selected weapon’s characteristics.','A unit-level reminder does not establish that every model or weapon is eligible.','Does a bonus against vehicles apply to a different target?','Only if that target satisfies the rule’s keywords and other conditions. Read the attack’s target, not just its expected damage.','04; 10.02','act'),
   core('shooting-after','After Shooting','Resolve effects triggered by that unit’s completed shooting before choosing the next unit. Repeat the selection and attacks sequence for the units you choose to shoot with.','Earlier shooting can enable a later unit’s benefits; check the actual provider and target.','Could an earlier shooter help a later unit?','Possibly: check whether it hit a qualifying target and whether the later unit meets the benefit’s conditions. The army reminders below explain the roster-specific checks.','10.02; specific ability triggers','after'),
   core('shooting-end','End of Shooting','Resolve rules that explicitly trigger at the end of the Shooting phase. Review any effects that expire now before entering Charge.','“After a unit shoots” and “end of phase” do not mean the same thing.','Can you delay a just-after-shooting trigger until now?','Do not assume so. Resolve each ability in its specified window, and check the rules for simultaneous triggers where necessary.','10.03','end')
  ]},
  {name:'Charge',intro:'Check eligibility, roll, then determine which charge move is possible.',steps:[
   core('charge-start','Start of Charge','Resolve rules triggered at the start of the active player’s Charge phase.','Start with the timing window before choosing a charging unit.','Did an earlier move or ability prevent a charge?','Check the unit’s movement and every restriction still lasting this turn. An exception for one move type does not cancel unrelated charge restrictions.','11.01','start'),
   core('charge-declare','Charge Rolls','Choose a unit that can declare a charge and has not done so this phase. General restrictions include being engaged, having Advanced or Fallen Back, or lacking an enemy within 12 inches. Roll 2D6 to establish the maximum charge-move distance.','In this edition, the detailed charge-target selection belongs to making the move after the roll.','Does a high roll cancel an eligibility restriction?','No. The unit must first be eligible to declare the charge. A specific rule may create an exception, but the dice alone do not.','11.02','select'),
   core('charge-move','Charge Moves','For the charge move, select targets within both 12 inches and the rolled maximum distance. The final position must engage every charge target and no non-target enemy unit. Check model-level movement requirements and coherency.','A distance that looks sufficient may still fail because no legal final position exists.','What if a legal charge move is impossible?','The charge is resolved without that move. You may also choose not to make the move. A completed charge grants Fights First until the turn ends.','11.02–11.04','act'),
   core('charge-end','End of Charge','Resolve end-of-Charge rules. Notice which units actually completed charge moves and what effects carry into Fight.','The next phase begins with its own pile-in step, before units are selected to fight.','Does declaring a charge alone grant Fights First?','No. The charge-move rule grants it after the move. Distinguish a declaration, a roll, and a completed legal move.','11.03–11.04','end')
  ]},
  {name:'Fight',intro:'Follow the 11th-edition order: pile in, resolve fights, then consolidate.',steps:[
   core('fight-start','Start of Fight','Both armies participate in this phase. Resolve start-of-Fight rules before the separate pile-in step.','The opponent’s turn does not mean your engaged units are inactive.','Are you only watching during the opponent’s Fight phase?','No. Both players resolve eligible units, subject to the current sequence and any relevant exceptions.','12.01','start'),
   core('fight-pile','Pile In','The active player resolves the optional pile-in moves they choose with eligible units, then the other player does so. A unit may make no more than one pile-in move in this step. Check the full target and positioning requirements.','Do not insert a routine pile-in before every selected unit fights: this edition has a separate pile-in step.','Can every model in an eligible unit freely move 3 inches?','No. Models in base contact cannot move, and the move has target, closer-to, engagement, and coherency conditions. Some abilities modify the distance but not every restriction.','12.02–12.03','pile'),
   core('fight-resolve','Fight','Begin Fights First selections with the active player and alternate eligible units. When that group is exhausted, the player who moves the sequence into Remaining Combats makes the next selection. Alternate until eligible fights are resolved; return to Fights First if an eligible Fights First unit appears.','Do not replace this with a blanket “the non-active player always picks first” rule.','Who gets the next remaining-combat choice?','It depends on who transitions the sequence out of Fights First. Follow section 12.04 rather than assuming a fixed player. Select a legal normal or overrun fight type for the chosen unit.','12.04–12.06','act'),
   core('fight-consolidate','Consolidate','After the Fight step, the active player resolves their chosen eligible consolidation moves, then the opponent. Select the required consolidation mode based on engagement, nearby enemies, or objectives, and check its conditions.','An engaging consolidation can give an enemy that has not fought a new opportunity to fight.','Is consolidation always a free move toward an objective?','No. The applicable mode has priority and restrictions. If you engage an enemy that has not fought, follow the extra fight instructions before continuing.','12.07–12.08','consolidate'),
   core('fight-end','End of Fight','Resolve the end-of-Fight window. Check remaining end-of-turn rules in their own window before passing the turn.','Some effects last a phase, others a turn or until a later Command phase.','Does every buff disappear at this point?','No. Read each effect’s duration. End of Fight and end of turn are distinct triggers; do not expire a longer effect early.','12.09; specific durations','end')
  ]}
 ];
 const abilities=[];
 function add(id,name,units,phase,turn,window,summary,conditions,question,answer,options={}){abilities.push({id,name,units,phase,turn,window,summary,conditions,question,answer,status:'community-checked',sourceIds:['community'],...options});}
 add('battle-focus','Battle Focus',[],[0],'either','round','Start each battle round with the Battle Focus allocation for the game size. Unspent tokens expire at the end of that battle round.',['Army rule must apply. Strike Force grants 4 tokens; Incursion 2; Onslaught 6.','Spending a token needs a matching Agile Manoeuvre trigger. Each unit normally performs at most one per phase; each manoeuvre is normally once per phase unless stated otherwise.'],'Do these tokens refresh at the start of both players’ turns?','No. The allocation is per battle round. This reminder appears before the first player’s Command phase, not before every Command phase.');
 add('eldrad-cp','Diviner of Futures',['Eldrad Ulthran'],[0],'you','start','Eldrad adds 1 CP at the start of your Command phase if he is on the battlefield.',['Not merely present in the roster: Eldrad must be on the battlefield.','This is additional to the Core CP both players gain in the following step.'],'Does Eldrad generate this CP in the opponent’s Command phase?','No. His rule specifies the start of your Command phase.');
 add('doom','Doom',['Eldrad Ulthran'],[1],'you','end','At the end of your Movement phase, Eldrad can select a visible enemy within 18 inches. Friendly Aeldari attacks against that target receive +1 to wound until the start of your next Command phase.',['Check Eldrad’s battlefield presence, visibility and range when selecting the target.','Only attacks against the selected enemy get this effect; apply normal modifier rules.'],'Is Doom limited to your Shooting phase?','Its stated duration extends beyond that phase. Check the target and the expiry at the start of your next Command phase.');
 add('whirling','Whirling Death',['Jain Zar'],[1],'you','act','While Jain Zar leads the unit, an Advance uses a fixed 6-inch increase instead of an Advance roll, and its Advance movement ignores vertical distance.',['Jain Zar must still be leading the unit.','This changes the Advance; it does not make the unit’s full move distance 6 inches.'],'Can you reroll the Advance roll here?','There is no Advance roll when this rule replaces it. Check other modifiers and restrictions separately.');
 add('strategist','Superlative Strategist',['Autarch'],[1],'either','act','While the Autarch leads a unit, that unit may reroll Advance rolls and rolls made while performing an Agile Manoeuvre.',['Applies only while leading.','An Advance-roll reroll cannot be used when another rule means no Advance roll is made.'],'Does this automatically reroll any movement-related die?','No. The wording identifies Advance rolls and rolls during an Agile Manoeuvre, not every movement-related roll.');
 add('flickerjump','Flickerjump',['Warp Spiders'],[1],'you','act','When selected for a Normal move in your Movement phase, the Spiders can use a 24-inch Move characteristic. They cannot declare a charge that turn, and must resolve the ability’s end-of-phase risk.',['Choose at the Normal-move selection window.','At the end of the phase roll once per model; each 1 inflicts a mortal wound on the unit.'],'Is this simply a longer move with no tradeoff?','No. Remember both the charge restriction and the pending risk roll, even if the move itself is already finished.');
 add('flickerjump-risk','Flickerjump: resolve the risk',['Warp Spiders'],[1],'you','end','If this unit used Flickerjump, now roll a D6 per model; each result of 1 causes one mortal wound to the unit.',['Only if Flickerjump was actually used this phase.','The charge restriction still lasts until the end of the turn.'],'Should a unit that chose an ordinary Normal move roll?','No. This consequence is conditional on using Flickerjump.');
 add('hawks','Grenade Pack Flyover',['Swooping Hawks'],[1],'you','act','Once per turn, after setup or after a Normal, Advance or Fall Back move, a Hawks unit can pick a visible enemy within 8 inches. Roll per Hawks model; 4+ results inflict mortal wounds, capped at 6.',['This is in your Movement phase.','After using it, that unit cannot be targeted by the Explosives Stratagem for the rest of the turn.'],'Do you count an attached character as a Swooping Hawk model?','The roll count specifies Swooping Hawks models. Check the model identities rather than assuming every model in an attached unit counts.');
 add('swift','Swift as the Wind',[],[1],'either','act','A Battle Focus option at selection for a Normal, Advance or Fall Back move increases the models’ Move characteristic by 2 inches for the phase.',['Spend a token on an eligible Battle Focus unit.','This manoeuvre may be used more than once in a phase with different units; the per-unit manoeuvre limit still applies.'],'Does a move-end trigger let you apply this retroactively?','No. This choice is at move selection.');
 add('flitting','Flitting Shadows',[],[1,3],'you','select','A Battle Focus option can prevent enemy Fire Overwatch against the selected unit for the rest of the turn.',['Trigger: selection for a Normal, Advance or Fall Back move, setup on the battlefield, or declaring a charge.','Spend a token, check the unit’s eligibility and the phase limits.'],'Can you wait for Overwatch to resolve and then cancel it?','No. Use the stated trigger window, not a later attack result.');
 add('star-engines','Star Engines',['Wave Serpent','Falcon'],[1],'you','act','When an eligible Vehicle is selected to Advance, this Battle Focus option gives its ranged weapons Assault until the turn ends.',['Requires the Vehicle keyword, Battle Focus eligibility and a token.','The trigger is Advance selection, not after shooting.'],'Does this grant Assault to passengers as well?','The effect describes the vehicle unit’s weapons. Do not extend it to a different unit without a rule doing so.',{sourceIds:['community','pack']});
 add('opportunity','Opportunity Seized',[],[1],'opponent','act','After an enemy finishes a Fall Back move, an eligible non-Titanic Battle Focus unit that began the phase engaged with it can use this manoeuvre for a D6+1-inch Normal move.',['Spend a token and check the phase’s manoeuvre limits.','The response is after the enemy move ends. The starting engagement condition still matters.'],'Can any nearby unit make this response?','No. The rule requires the responding unit to have started the phase engaged with that enemy.');
 add('fade','Fade Back',[],[2],'opponent','after','Just after an enemy shoots, a qualifying non-Titanic Battle Focus unit hit by those attacks can spend a token for a D6+1-inch Normal move.',['Requires a hit, not necessarily a lost wound.','Check all eligibility and phase-use restrictions before moving.'],'Can you save this response until every enemy unit has shot?','No. It is a just-after-this-unit-shoots window.');
 add('sudden','Sudden Strike',[],[3],'you','act','At the end of a qualifying charge move, this Battle Focus manoeuvre raises the unit’s pile-in and consolidation distance to 6 inches for the turn.',['A completed charge move and an available token are required.','Distance changes do not remove the movement’s other conditions.'],'Do you activate it when selecting a unit to fight?','No. Its trigger is when that unit’s charge move ends.',{sourceIds:['community','pack']});
 add('path-warrior','Path of the Warrior',[],[2,4],'either','select','When an eligible Aspect Warriors or Avatar of Khaine unit is selected to shoot or fight, choose rerolls of hit rolls of 1 or wound rolls of 1 for that unit until the phase ends.',['Requires Aspect Host and the appropriate unit keyword or Avatar identity.','Make the selection at the ability’s trigger, not after seeing attack results.'],'Does the unit receive both rerolls automatically?','No. This rule offers a choice. Your exported enhancement is Aspect of Murder, not Mantle of Wisdom, which is a separate rule.',{detachment:'Aspect Host'});
 add('asurmen-hand','Hand of Asuryan',['Asurmen'],[2],'you','select','Once in the battle, when Asurmen is selected to shoot, his Bloody Twins can gain Damage 3, Anti-Infantry 5+ and Devastating Wounds for that phase.',['The effect applies to his specified weapon, not every model in his attached unit.','Declare at selection to shoot; keep track of whether the battle-use remains.'],'Does it improve the Dire Avengers’ catapults too?','No. Its weapon scope is Asurmen’s Bloody Twins.',{sourceIds:['pack'],status:'official-checked'});
 add('bladestorm','Bladestorm',['Dire Avengers'],[2],'you','act','Ranged weapons in the unit gain Sustained Hits 1 against a target within half range.',['Check half range for the relevant weapon and target.','Any attached-model interactions and existing keywords still need the current rules applied.'],'Is half range measured once for the whole army?','No. Check the attacking weapon’s range and the target.');
 add('token','Aspect Shrine Token',['Dire Avengers','Howling Banshees','Dark Reapers','Fire Dragons','Swooping Hawks','Warp Spiders'],[2,4],'either','act','A remaining token can turn one hit or wound result for a non-Character model in that unit into an unmodified 6. Each token is available once per battle.',['The unit must actually have an unspent Aspect Shrine Token.','Character models are explicitly excluded, including attached leaders.'],'Can a token improve Asurmen’s own roll?','No. He is a Character even when attached to Dire Avengers. Token count belongs to the equipped unit, not every model.',{sourceIds:['pack'],status:'official-checked'});
 add('reapers','Inescapable Accuracy',['Dark Reapers'],[2],'you','act','For the unit’s ranged attacks, you may ignore any or all modifiers to Ballistic Skill and to the hit roll.',['This does not automatically ignore other defensive rules, saving throws or damage reductions.'],'Can you ignore a damage modifier with this ability?','No. Its scope is Ballistic Skill and hit-roll modifiers.');
 add('dragons','Assured Destruction',['Fire Dragons'],[2],'you','act','In your Shooting phase, attacks against a Monster or Vehicle unit can reroll hit, wound and damage rolls.',['The target must have one of those qualifying keywords.','Apply the rule to the specified ranged attacks, not every future attack.'],'Does it grant the same rerolls against ordinary infantry?','Not on the basis of this ability. Confirm the target’s keywords.');
 add('walker','Crystalline Targeting',['War Walkers'],[2],'you','after','After the Walkers shoot, choose an enemy they hit. Friendly Aeldari attacks against it improve AP by 1 until this phase ends.',['There must have been a hit on the selected enemy.','Each enemy unit can be selected for this ability only once per turn.'],'Why might you choose the Walkers earlier in the shooting order?','Their marked target can help subsequent Aeldari attacks. The effect does not retroactively change attacks already resolved.');
 add('falcon','Fire Support',['Falcon'],[2],'you','after','After the Falcon shoots, choose an enemy it hit. Friendly models that disembarked from that Falcon this turn may reroll wounds against that enemy until the turn ends.',['The benefiting models must have disembarked from this transport this turn.','The target must have been hit by the Falcon’s attacks.'],'Does a nearby Fire Dragons unit qualify without disembarking?','No. Proximity alone does not meet the passenger condition.');
 add('asurmen-move','Tactical Acumen',['Asurmen'],[2],'you','after','While Asurmen leads the unit, after it shoots in your Shooting phase it can make a Normal move of up to 6 inches. Taking that move prevents charging for the rest of the turn.',['Asurmen must still be leading.','This is a move after that unit shoots, not the end-of-phase window.'],'Can the unit shoot, take this move, then charge?','Not under this rule: choosing its move adds a charge restriction.');
 add('acrobatic','Acrobatic',['Howling Banshees'],[3],'you','select','Howling Banshees can declare a charge after Advancing or Falling Back that turn.',['This exception addresses those two move types.','It does not cancel a separate charge prohibition from a disembark mode or another ability.'],'Can “advance and charge” override every other restriction?','No. Read the scope of each exception and each remaining restriction.');
 add('avatar-aura','The Bloody-Handed',['Avatar of Khaine'],[1,3],'you','act','Friendly Aeldari units within 6 inches of the Avatar receive +1 on Advance and Charge rolls.',['Check the aura’s distance when applying the roll modifier.','A fixed movement replacement is not an Advance roll.'],'Does Jain Zar’s fixed Advance become an Advance roll?','No. A fixed replacement and a roll modifier are different mechanics.');
